def apply_hysteresis(flag_series, confirm_days=3):
    confirmed = flag_series.copy()
    pending_flag = None
    pending_count = 0

    for i in range(1, len(flag_series)):
        raw = flag_series.iloc[i]
        current_confirmed = confirmed.iloc[i - 1]

        if raw == current_confirmed:
            pending_flag = None
            pending_count = 0
        else:
            if raw == pending_flag:
                pending_count += 1
            else:
                pending_flag = raw
                pending_count = 1

            if pending_count >= confirm_days:
                current_confirmed = raw
                pending_flag = None
                pending_count = 0

        confirmed.iloc[i] = current_confirmed

    return confirmed

nifty_df['trend_flag_confirmed'] = apply_hysteresis(nifty_df['trend_flag'], confirm_days=3)
